package com.campus.market.auth;
import com.campus.market.common.GlobalExceptionHandler;
import com.campus.market.user.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.data.redis.core.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@SpringBootTest(properties={"spring.datasource.url=${LESSON68_DB_URL:jdbc:mysql://127.0.0.1:1/disabled}","spring.datasource.username=root","spring.datasource.password=","market.login-protection.enabled=true","market.login-protection.prefix=campus:lesson113:test:","market.login-protection.port=${LESSON68_REDIS_PORT:1}","market.registration-protection.enabled=true","market.registration-protection.limit=3","market.registration-protection.window-seconds=60","market.product-cache.enabled=false","market.orders.mq.enabled=false","market.notifications.mq.enabled=false","springdoc.api-docs.enabled=false"})
@AutoConfigureMockMvc @TestInstance(TestInstance.Lifecycle.PER_CLASS)
@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
@EnabledIfEnvironmentVariable(named="LESSON68_DB_URL",matches="jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/campus_lesson68_verify\\?.*")
class RegistrationRateLimitIntegrationTest {
 @Autowired UserService actualUserService;@Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired LoginRateLimiter store;@Autowired RegistrationRateLimiter protection;@Autowired SessionService sessions;
 final String prefix="campus:lesson113:test:";final JsonMapper json=JsonMapper.builder().build();LettuceConnectionFactory factory;StringRedisTemplate redis;int port;
 @BeforeAll void redis(){port=Integer.parseInt(System.getenv("LESSON68_REDIS_PORT"));factory=new LettuceConnectionFactory("127.0.0.1",port);factory.afterPropertiesSet();factory.start();redis=new StringRedisTemplate(factory);}
 @AfterAll void close(){if(factory!=null)factory.destroy();}
 @BeforeEach void clear(){assertTrue(System.getenv("LESSON68_DB_URL").contains("/campus_lesson68_verify?"));try(var cursor=redis.scan(ScanOptions.scanOptions().match(prefix+"*").build())){cursor.forEachRemaining(redis::delete);}jdbc.update("DELETE FROM login_sessions");jdbc.update("DELETE FROM users");}
 MockHttpServletRequestBuilder register(String name){return post("/api/users/register").contentType("application/json").content(json.writeValueAsString(Map.of("username",name,"password","Campus2026!","nickname","注册防刷验收")));}
 long users(){return jdbc.queryForObject("SELECT COUNT(*) FROM users",Long.class);}
 List<String> keys(){var result=new ArrayList<String>();try(var cursor=redis.scan(ScanOptions.scanOptions().match(prefix+"*").build())){cursor.forEachRemaining(result::add);}return result;}
 String key(){return keys().stream().filter(k->k.endsWith(":registration")).findFirst().orElseThrow();}
 LoginRateLimiter custom(int target){return new LoginRateLimiter(true,"127.0.0.1",target,"",prefix,5,900,30,60);}
 MockMvc standalone(UserService service,RegistrationRateLimiter limiter){return MockMvcBuilders.standaloneSetup(new UserController(service,limiter)).setControllerAdvice(new GlobalExceptionHandler()).build();}
 @Test void threeAllowedThenFourth429CreatesNoFourthUser()throws Exception{for(int i=0;i<3;i++)assertEquals(201,mvc.perform(register("register_"+i)).andReturn().getResponse().getStatus());var r=mvc.perform(register("register_3")).andReturn().getResponse();assertEquals(429,r.getStatus());assertEquals("REGISTRATION_RATE_LIMITED",json.readTree(r.getContentAsByteArray()).path("code").asString());assertEquals(3,users());}
 @Test void rateLimitedResponseIsNoStoreWithBoundedRetryAfter()throws Exception{for(int i=0;i<3;i++)protection.check("127.0.0.1");var r=mvc.perform(register("register_ok")).andReturn().getResponse();assertEquals(429,r.getStatus());long seconds=Long.parseLong(r.getHeader("Retry-After"));assertTrue(seconds>=1&&seconds<=60);assertEquals("no-store",r.getHeader("Cache-Control"));assertEquals("no-cache",r.getHeader("Pragma"));assertEquals(0,users());}
 @Test void rejectedAttemptDoesNotExtendWindowOrIncrementCounter()throws Exception{for(int i=0;i<3;i++)protection.check("127.0.0.1");long before=redis.getExpire(key(),TimeUnit.MILLISECONDS);assertThrows(RegistrationRateLimitedException.class,()->protection.check("127.0.0.1"));assertEquals("3",redis.opsForValue().get(key()));assertTrue(redis.getExpire(key(),TimeUnit.MILLISECONDS)<=before);}
 @Test void distinctConnectionAddressesHaveIndependentBudgets(){for(int i=0;i<3;i++)protection.check("127.0.0.1");assertThrows(RegistrationRateLimitedException.class,()->protection.check("127.0.0.1"));assertDoesNotThrow(()->protection.check("127.0.0.2"));assertEquals(2,keys().size());}
 @Test void forwardedHeadersDoNotCreateNewBudget()throws Exception{for(int i=0;i<3;i++)protection.check("127.0.0.1");var r=mvc.perform(register("register_proxy").header("X-Forwarded-For","198.51.100.7").header("Forwarded","for=198.51.100.8")).andReturn().getResponse();assertEquals(429,r.getStatus());assertEquals(0,users());}
 @Test void ipv4MappedRepresentationSharesCounter(){protection.check("127.0.0.1");protection.check("::ffff:127.0.0.1");protection.check("127.0.0.1");assertThrows(RegistrationRateLimitedException.class,()->protection.check("::ffff:127.0.0.1"));assertEquals(1,keys().size());}
 @Test void ipv6EquivalentRepresentationSharesCounter(){protection.check("::1");protection.check("0:0:0:0:0:0:0:1");protection.check("::1");assertThrows(RegistrationRateLimitedException.class,()->protection.check("0:0:0:0:0:0:0:1"));assertEquals(1,keys().size());}
 @Test void rawAddressUsernameAndPasswordDoNotAppearInRedisKeysOrValues(){protection.check("198.51.100.9");assertTrue(key().matches("campus:lesson113:test:\\{[a-f0-9]{64}\\}:registration"));assertEquals("1",redis.opsForValue().get(key()));assertFalse(key().contains("198.51.100.9"));}
 @Test void invalidPayloadAfterBindingConsumesAdmittedQuota()throws Exception{for(int i=0;i<3;i++)assertEquals(400,mvc.perform(register("BAD NAME")).andReturn().getResponse().getStatus());assertEquals(429,mvc.perform(register("register_good")).andReturn().getResponse().getStatus());assertEquals(0,users());}
 @Test void malformedJsonDoesNotReachControllerOrCreateCounter()throws Exception{assertEquals(400,mvc.perform(post("/api/users/register").contentType("application/json").content("{")).andReturn().getResponse().getStatus());assertTrue(keys().isEmpty());assertEquals(0,users());}
 @Test void duplicateUsernameConsumesQuotaAndCannotCreateDuplicate()throws Exception{assertEquals(201,mvc.perform(register("register_dup")).andReturn().getResponse().getStatus());for(int i=0;i<2;i++)assertEquals(409,mvc.perform(register("register_dup")).andReturn().getResponse().getStatus());assertEquals(429,mvc.perform(register("register_dup")).andReturn().getResponse().getStatus());assertEquals(1,users());}
 @Test void registrationLimitDoesNotBlockCorrectLogin()throws Exception{assertEquals(201,mvc.perform(register("register_login")).andReturn().getResponse().getStatus());protection.check("127.0.0.1");protection.check("127.0.0.1");assertThrows(RegistrationRateLimitedException.class,()->protection.check("127.0.0.1"));var r=mvc.perform(post("/api/users/login").contentType("application/json").content(json.writeValueAsString(Map.of("username","register_login","password","Campus2026!")))).andReturn().getResponse();assertEquals(200,r.getStatus());}
 @Test void loginFailureBudgetDoesNotConsumeRegistrationBudget(){for(int i=0;i<5;i++)store.failed(store.begin("missing_account","127.0.0.1"));for(int i=0;i<3;i++)assertDoesNotThrow(()->protection.check("127.0.0.1"));assertEquals("3",redis.opsForValue().get(key()));}
 @Test void atomicConcurrencyAdmitsExactlyConfiguredCount()throws Exception{var pool=Executors.newFixedThreadPool(12);var start=new CountDownLatch(1);try{List<Future<Boolean>> results=new ArrayList<>();for(int i=0;i<36;i++)results.add(pool.submit(()->{start.await();try{protection.check("127.0.0.1");return true;}catch(RegistrationRateLimitedException expected){return false;}}));start.countDown();int allowed=0;for(var f:results)if(f.get(5,TimeUnit.SECONDS))allowed++;assertEquals(3,allowed);assertEquals("3",redis.opsForValue().get(key()));}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}
 @Test void limitIsEnforcedBeforeCallingDatabaseOrPasswordHash()throws Exception{var service=mock(UserService.class);when(service.register(any())).thenReturn(new UserResponse(1,"register_mock","验收"));var local=standalone(service,protection);for(int i=0;i<3;i++)assertEquals(201,local.perform(register("register_mock")).andReturn().getResponse().getStatus());assertEquals(429,local.perform(register("register_mock")).andReturn().getResponse().getStatus());verify(service,times(3)).register(any());assertEquals(0,users());}
 @Test void shortWindowExpiresAndFirstNewAttemptGetsNewQuota()throws Exception{var shortLimit=new RegistrationRateLimiter(store,true,1,1);shortLimit.check("127.0.0.1");assertThrows(RegistrationRateLimitedException.class,()->shortLimit.check("127.0.0.1"));Thread.sleep(1100);assertDoesNotThrow(()->shortLimit.check("127.0.0.1"));assertEquals("1",redis.opsForValue().get(key()));}
 @Test void invalidCounterFailsClosedWithoutReplacingIt(){protection.check("127.0.0.1");redis.opsForValue().set(key(),"not-a-number",Duration.ofSeconds(30));assertThrows(RegistrationProtectionUnavailableException.class,()->protection.check("127.0.0.1"));assertEquals("not-a-number",redis.opsForValue().get(key()));assertEquals(0,users());}
 @Test void missingTtlFailsClosedWithoutRepairingOrGrantingQuota(){protection.check("127.0.0.1");redis.persist(key());assertThrows(RegistrationProtectionUnavailableException.class,()->protection.check("127.0.0.1"));assertEquals(-1,redis.getExpire(key()));assertEquals("1",redis.opsForValue().get(key()));}
 @Test void wrongRedisTypeFailsClosed(){var other=custom(port);try{var gate=new RegistrationRateLimiter(other,true,3,60);gate.check("127.0.0.1");String k=key();redis.delete(k);redis.opsForHash().put(k,"private","fixture");assertThrows(RegistrationProtectionUnavailableException.class,()->gate.check("127.0.0.1"));assertEquals(1,redis.opsForHash().size(k));}finally{other.destroy();}}
 @Test void unreachableRedisReturns503AndNeverCallsUserService()throws Exception{int unused;try(var socket=new java.net.ServerSocket(0)){unused=socket.getLocalPort();}var other=custom(unused);try{var service=mock(UserService.class);var local=standalone(service,new RegistrationRateLimiter(other,true,3,60));var r=local.perform(register("register_outage")).andReturn().getResponse();assertEquals(503,r.getStatus());assertEquals("REGISTRATION_PROTECTION_UNAVAILABLE",json.readTree(r.getContentAsByteArray()).path("code").asString());assertEquals("5",r.getHeader("Retry-After"));assertEquals("no-store",r.getHeader("Cache-Control"));verifyNoInteractions(service);assertEquals(0,users());}finally{other.destroy();}}
 @Test void disabledFeatureDoesNotReadOrWriteRedis(){var gate=new RegistrationRateLimiter(store,false,1,1);for(int i=0;i<10;i++)gate.check("not-an-ip");assertTrue(keys().isEmpty());}
 @Test void invalidPolicyOrMissingSharedConnectionRejectedAtConstruction(){for(int[] policy:List.of(new int[]{0,1},new int[]{10001,1},new int[]{1,0},new int[]{1,86401}))assertThrows(IllegalArgumentException.class,()->new RegistrationRateLimiter(store,true,policy[0],policy[1]));var disabled=new LoginRateLimiter(false,"127.0.0.1",port,"",prefix,5,900,30,60);assertThrows(IllegalArgumentException.class,()->new RegistrationRateLimiter(disabled,true,3,60));}
 @Test void nonLiteralOrInvalidAddressesCannotTriggerDnsOrCreateKeys(){for(String ip:List.of("localhost","https://evil.invalid","127.00.0.1","300.1.1.1","::1%lo0",""))assertThrows(RegistrationProtectionUnavailableException.class,()->protection.check(ip));assertTrue(keys().isEmpty());}
 @Test void corsExposesRetryAfterAndCorrelationHeader()throws Exception{for(int i=0;i<3;i++)protection.check("127.0.0.1");var r=mvc.perform(register("register_cors").header("Origin","http://localhost:5173")).andReturn().getResponse();assertEquals(429,r.getStatus());String exposed=r.getHeader("Access-Control-Expose-Headers");assertTrue(exposed.contains("Retry-After"));assertTrue(exposed.contains("X-Request-Id"));}
 @Test void successfulRegistrationIsNoStoreAndCreatesNoLoginSession()throws Exception{var r=mvc.perform(register("register_private")).andReturn().getResponse();assertEquals(201,r.getStatus());assertEquals("no-store",r.getHeader("Cache-Control"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM login_sessions",Long.class));assertFalse(r.getContentAsString().contains("password"));}
 @Test void realRedisAdmissionAndLimitEachIncrementOneOutcome(){var registry=new io.micrometer.core.instrument.simple.SimpleMeterRegistry();try{var metrics=new RegistrationMetrics(registry,true,1,60);var gate=new RegistrationRateLimiter(store,true,1,60,metrics);gate.check("127.0.0.1");assertThrows(RegistrationRateLimitedException.class,()->gate.check("127.0.0.1"));assertEquals(1,registry.get("campus.registration.decisions").tag("outcome","allowed").counter().count());assertEquals(1,registry.get("campus.registration.decisions").tag("outcome","limited").counter().count());}finally{registry.close();}}
 @Test void validationFailureIsAdmittedButIsNotRegistrationSuccess()throws Exception{var registry=new io.micrometer.core.instrument.simple.SimpleMeterRegistry();try{var metrics=new RegistrationMetrics(registry,true,3,60);var gate=new RegistrationRateLimiter(store,true,3,60,metrics);assertEquals(400,standalone(actualUserService,gate).perform(register("BAD NAME")).andReturn().getResponse().getStatus());assertEquals(1,registry.get("campus.registration.decisions").tag("outcome","allowed").counter().count());assertEquals(0,users());}finally{registry.close();}}
 @Test void realRedisInvalidCounterRecordsUnavailableAndDoesNotReplaceValue(){var registry=new io.micrometer.core.instrument.simple.SimpleMeterRegistry();try{var metrics=new RegistrationMetrics(registry,true,3,60);var gate=new RegistrationRateLimiter(store,true,3,60,metrics);gate.check("127.0.0.1");redis.opsForValue().set(key(),"corrupt",Duration.ofSeconds(30));assertThrows(RegistrationProtectionUnavailableException.class,()->gate.check("127.0.0.1"));assertEquals(1,registry.get("campus.registration.decisions").tag("outcome","unavailable").counter().count());assertEquals("corrupt",redis.opsForValue().get(key()));}finally{registry.close();}}
 @Test void disabledMetricsDoNotTouchActualRedis(){var registry=new io.micrometer.core.instrument.simple.SimpleMeterRegistry();try{var metrics=new RegistrationMetrics(registry,false,3,60);new RegistrationRateLimiter(store,false,3,60,metrics).check("not-an-address");assertEquals(1,registry.get("campus.registration.decisions").tag("outcome","disabled").counter().count());assertTrue(keys().isEmpty());}finally{registry.close();}}
}
